mapper.select:
SELECT course_id, current_revision FROM learning_event_origins
WHERE user_id = #{userId} AND origin_kind = #{originKind} AND origin_id = #{originId}
FOR UPDATE

SELECT * FROM learning_events
WHERE user_id = #{userId} AND origin_kind = #{originKind} AND origin_id = #{originId}
  AND origin_revision = #{revision}
ORDER BY output_no
FOR UPDATE

choose.when:
SELECT r.user_id, i.course_id FROM execution_records r
JOIN execution_items i ON i.execution_item_id = r.execution_item_id
WHERE r.execution_record_id = #{originId}

SELECT p.user_id, t.course_id FROM topic_progress p
JOIN course_topics t ON t.topic_id = p.topic_id
WHERE p.topic_progress_id = #{originId}

SELECT m.user_id, c.course_id FROM ai_messages m
JOIN ai_conversations c ON c.conversation_id = m.conversation_id
WHERE m.message_id = #{originId}

SELECT r.user_id, r.course_id FROM routine_exceptions x
JOIN routines r ON r.routine_id = x.routine_id
WHERE x.routine_exception_id = #{originId}

mapper.select:
SELECT topic_id FROM course_topics
WHERE user_id = #{userId} AND course_id = #{courseId} AND topic_id IN
#{id}

SELECT COUNT(*) FROM course_topics t
JOIN textbook_ref_aliases a
  ON a.user_id = t.user_id AND a.book_key_hash = SHA2(t.source_textbook_key, 256)
 AND a.book_key = t.source_textbook_key AND a.book_ref_id = #{bookRefId}
WHERE t.user_id = #{userId} AND t.course_id = #{courseId}
  AND t.toc_key_state = 'SET' AND t.toc_key_hash = #{keyHash} AND t.toc_key_line = #{keyLine}
